from pathlib import Path
from datetime import datetime, timezone
import hashlib,json,collections
root=Path('/workspace/ir-agent')
base=root/'research/ir-case-studies-2026-10-15'
target=base/'3774/faq-to-filing-guidance-comparison'
read_files={}
def readbytes(p):
 p=Path(p); p=p if p.is_absolute() else root/p
 b=p.read_bytes();read_files[str(p.relative_to(root))]=hashlib.sha256(b).hexdigest();return b
