def check(name,actual,expected,**extra):
 ok=actual==expected
 d={'check':name,'pass':ok,'actual':actual,'expected':expected,**extra};checks.append(d)
 if not ok:issues.append(d)
 return ok
def artifact(path,declared,context):
 if path not in artifact_cache:
  data=readbytes(path);artifact_cache[path]={'data':json.loads(data),'sha256':hashlib.sha256(data).hexdigest()}
 a=artifact_cache[path]
 check('artifact_sha256',a['sha256'],declared,context=context,path=path)
 return a['data']
check('previous_index_sha256_in_v13',read_files[str((base/'disclosed-fact-index-v12.json').relative_to(root))],idx['previous_index_sha256'])
check('previous_index_sha256_in_parent',read_files[str((base/'disclosed-fact-index-v12.json').relative_to(root))],parent['previous_index_sha256'])
check('new_index_sha256_in_parent',read_files[str((base/'disclosed-fact-index-v13.json').relative_to(root))],parent['new_index_sha256'])
check('parent_new_index_path',parent['new_index'],str((base/'disclosed-fact-index-v13.json').relative_to(root)))
check('previous_entry_count',len(prev['companies']),15)
check('previous_fact_count',sum(len(e['facts']) for e in prev['companies']),67)
check('previous_15_entries_complete_object_equality',idx['companies'][:len(prev['companies'])],prev['companies'])
# Keep the potentially large equality comparison out of the report; its boolean is sufficient.
checks[-1].pop('actual');checks[-1].pop('expected')
for n,e in enumerate(idx['companies']):
 context={'entry':n,'company_id':e['company_id']}
 try:
  bundle=artifact(e['artifact'],e.get('artifact_sha256'),context)
  ss=[s for s in bundle.get('sources',[]) if s.get('id')==e['source_id']]
  check('entry_derived_source_unique',len(ss),1,**context)
  if ss:check('entry_derived_company',ss[0].get('company_id'),e['company_id'],**context)
  entry_checks.append({**context,'artifact':e['artifact'],'source_id':e['source_id'],'fact_count':len(e['facts']),'resolved':len(ss)==1})
 except Exception as ex:
  issues.append({'check':'entry_resolution_exception',**context,'error':str(ex)})
 for f in e['facts']:
  cx={**context,'fact_id':f['id']}
  paths={k:f.get(k,e.get(k)) for k in ['artifact','artifact_sha256','source_id','original_source_id']}
  start_issue_count=len(issues)
  try:
   bundle=artifact(paths['artifact'],paths['artifact_sha256'],cx)
   sources=[s for s in bundle.get('sources',[]) if s.get('id')==paths['source_id']]
   check('fact_derived_source_unique',len(sources),1,**cx)
   if len(sources)!=1:raise ValueError('derived source not unique')
   s=sources[0];content=json.loads(s['content'])
   check('fact_derived_company',s.get('company_id'),e['company_id'],**cx)
   matches=[q for q in content.get('facts',[]) if q.get('id')==f['id']]
   check('fact_id_unique_in_derived_content',len(matches),1,**cx)
   if len(matches)!=1:raise ValueError('fact id not unique')
   q=matches[0]
   excluded={'artifact','artifact_sha256','source_id','original_source_id','derived_source_imported_into_actual_database'}
   mismatches={k:{'index':v,'bundle':q.get(k),'bundle_key_present':k in q} for k,v in f.items() if k not in excluded and (k not in q or q[k]!=v)}
   check('index_fact_fields_equal_derived_content',mismatches,{},**cx)
   check('derived_content_original_source_id',content.get('original_source_id'),paths['original_source_id'],**cx)
   check('derived_metadata_original_source_id',s.get('metadata',{}).get('original_source_id'),paths['original_source_id'],**cx)
   check('fact_original_source_id',q.get('original_source_id'),paths['original_source_id'],**cx)
   originals=[o for o in bundle.get('sources',[]) if o.get('id')==paths['original_source_id']]
   check('original_source_unique_in_bundle',len(originals),1,**cx)
   if originals:check('original_source_company',originals[0].get('company_id'),e['company_id'],**cx)
   record_checks.append({**cx,**paths,'per_fact_override_fields':[k for k in paths if k in f],'pass':len(issues)==start_issue_count})
  except Exception as ex:
   issues.append({'check':'fact_resolution_exception',**cx,'error':str(ex)})
   record_checks.append({**cx,**paths,'pass':False,'error':str(ex)})
# Check source-integrity declarations once per artifact/source, without checking quotes, offsets or normalizing/recalculating facts.
snapshot_methods=[('canonical_utf8_sorted_compact',dict(ensure_ascii=False,sort_keys=True,separators=(',',':'))),('ascii_sorted_compact',dict(ensure_ascii=True,sort_keys=True,separators=(',',':'))),('utf8_sorted_default',dict(ensure_ascii=False,sort_keys=True)),('ascii_sorted_default',dict(ensure_ascii=True,sort_keys=True))]
unresolved_hash_declarations=[]
for ap,a in artifact_cache.items():
 bundle=a['data']
 for s in bundle.get('sources',[]):
  md=s.get('metadata',{})
  if md.get('provider')!='project_disclosed_fact_normalization':continue
  original_id=md.get('original_source_id')
  originals=[o for o in bundle.get('sources',[]) if o.get('id')==original_id]
  if len(originals)!=1:continue
  orig=originals[0];ct=json.loads(s['content'])
  actual_content=hashlib.sha256(orig['content'].encode('utf-8')).hexdigest()
  for scope,declaration in [('derived_metadata',md),('derived_content',ct)]:
   h=declaration.get('original_source_content_sha256')
   if h:
    ok=check('original_content_sha256',actual_content,h,artifact=ap,source_id=s['id'],declaration=scope)
    source_hash_checks.append({'artifact':ap,'source_id':s['id'],'kind':scope+'.original_source_content_sha256','pass':ok})
  declared=md.get('original_source_snapshot_sha256')
  if declared:
   matched=[name for name,kwargs in snapshot_methods if hashlib.sha256(json.dumps(orig,**kwargs).encode('utf-8')).hexdigest()==declared]
   if matched:
    source_hash_checks.append({'artifact':ap,'source_id':s['id'],'kind':'original_source_snapshot_sha256','pass':True,'serialization':matched})
   else:
    unresolved_hash_declarations.append({'artifact':ap,'source_id':s['id'],'kind':'original_source_snapshot_sha256','declared':declared,'reason':'No listed canonical JSON serialization matched; snapshot contract not assumed.'})
# All artifact SHA-bearing sidecar references in the index are checked as bytes only.
sidecar_checks=[]
for e in idx['companies']:
 pv=e.get('parent_verification')
 if isinstance(pv,dict) and pv.get('root_recheck') and pv.get('sha256'):
  actual=hashlib.sha256(readbytes(pv['root_recheck'])).hexdigest()
  ok=check('parent_verification_sha256',actual,pv['sha256'],path=pv['root_recheck'])
  sidecar_checks.append({'path':pv['root_recheck'],'pass':ok})
companies={e['company_id'] for e in idx['companies']}
pairs={(e['company_id'],f.get('original_source_id',e.get('original_source_id'))) for e in idx['companies'] for f in e['facts']}
new=idx['companies'][len(prev['companies']):]
counts={'previous_entries':len(prev['companies']),'previous_fact_records':sum(len(e['facts']) for e in prev['companies']),'derived_artifact_entries':len(idx['companies']),'fact_records':sum(len(e['facts']) for e in idx['companies']),'unique_companies':len(companies),'unique_company_original_source_pairs':len(pairs),'new_entries':len(new),'new_fact_records':sum(len(e['facts']) for e in new),'resolved_unique_normalized_artifact_paths':len(artifact_cache),'fact_records_with_per_fact_overrides':sum(bool(r.get('per_fact_override_fields')) for r in record_checks)}
for k,expected in [('derived_artifact_entries',17),('fact_records',75),('unique_companies',14),('unique_company_original_source_pairs',16),('new_entries',2),('new_fact_records',8)]:check('count_'+k,counts[k],expected)
for key,count_key in [('fact_count','fact_records'),('unique_company_count','unique_companies'),('company_source_entry_count','derived_artifact_entries'),('unique_original_company_source_pair_count','unique_company_original_source_pairs')]:check('index_declared_'+key,idx[key],counts[count_key])
for key,count_key in [('fact_record_count','fact_records'),('unique_company_count','unique_companies'),('derived_artifact_entry_count','derived_artifact_entries'),('unique_original_company_source_pair_count','unique_company_original_source_pairs'),('new_fact_records','new_fact_records')]:check('parent_declared_'+key,parent[key],counts[count_key])
check('parent_previous_entries_unchanged_declaration',parent['previous_15_entries_and_67_facts_unchanged'],idx['companies'][:15]==prev['companies'])
new_metrics={}
for e in new:
 for f in e['facts']:new_metrics.setdefault(f['concept'],[]).append({'company_id':e['company_id'],'kind':f['kind'],'value':f['value'],'unit':f['unit'],'period':f['period'],'id':f['id'],'original_source_id':f.get('original_source_id',e['original_source_id'])})
check('new_distinct_concepts',len(new_metrics),4)
for concept,rows in new_metrics.items():
 check('new_paired_displays_same_company_kind_value_unit',len({(r['company_id'],r['kind'],r['value'],r['unit']) for r in rows}),1,concept=concept)
 check('new_two_records_per_concept',len(rows),2,concept=concept)
 check('new_guidance_not_external_estimate',{r['kind'] for r in rows}=={'issuer_guidance'},True,concept=concept)
check('parent_distinct_guidance_quantities',parent['new_distinct_guidance_quantities_compared'],len(new_metrics))
check('parent_new_independent_forecasts',parent['new_independent_forecasts'],0)
summary={'counts':counts,'all_checks_pass':not issues,'check_count':len(checks),'issues':issues,'unresolved_hash_declarations':unresolved_hash_declarations,'source_hash_check_count':len(source_hash_checks),'source_snapshot_hash_matches':sum(r['kind']=='original_source_snapshot_sha256' for r in source_hash_checks),'new_concepts':list(new_metrics),'new_pair_details':new_metrics,'per_fact_overrides':[r for r in record_checks if r.get('per_fact_override_fields')],'artifact_paths':list(artifact_cache)}
